# -*- coding: utf-8 -*-
"""Generateur de generale-mat-part-D.json — fiches 'prototype' SVT et Biologie-ecologie.

12 fiches : S1..S9 (SVT, 2nde / 1re / Terminale spe) et BE1..BE3 (Biologie-ecologie).
Chaque fiche : 12 points, 9 questions (7 QCM + 2 texte), 7 blocs ordonnes, 3 schemas.
Sources : BO spécial n° 1 du 22 janvier 2019, programmes officiels SVT et
Biologie-ecologie, éduscol.
"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from fixtures import (fiche, qcm, qt, diag, svg_grille, svg_flux,
                      svg_compare, bloc, valider_et_ecrire)

FIL = ["generale"]

SRC_2NDE = ("Programme de sciences de la vie et de la Terre de classe de seconde, "
            "BO spécial n° 1 du 22 janvier 2019 (arrêté du 17 juillet 2018) · éduscol")
SRC_1RE = ("Programme de sciences de la vie et de la Terre de classe de premiere, "
           "BO spécial n° 1 du 22 janvier 2019 (arrêté du 17 juillet 2018) · éduscol")
SRC_TLE = ("Programme de sciences de la vie et de la Terre de classe terminale, specialite SVT, "
           "BO spécial n° 1 du 22 janvier 2019 (arrêté du 17 juillet 2018) · éduscol")
SRC_BE = ("Programme de specialite Biologie-ecologie, BO spécial n° 1 du 22 janvier 2019 "
          "(arrêté du 17 juillet 2018) · éduscol, ressources biologie-ecologie")

MAT_SVT = "SVT"
MAT_BE = "Biologie-écologie"

F = []


# --------------------------------------------------------------------------
# Raccourcis de construction
# --------------------------------------------------------------------------
def mk(annees, matiere, titre, source, points, questions, affichage, schema):
    return fiche(FIL, annees, matiere, titre, source, points, questions, affichage, schema)


def B_intro(t):
    return bloc("L'idee en une phrase", type="intro", texte=t)


def B_formule(eq, leg, titre="La relation cle a connaitre"):
    return bloc(titre, type="formule", eq=eq, leg=leg)


def B_grille(items, titre="Tableau de synthese"):
    return bloc(titre, type="grille", items=items)


def B_liste(items, titre="A retenir"):
    return bloc(titre, type="liste", items=items)


def B_etapes(items, titre="Methode pas a pas"):
    return bloc(titre, type="etapes", items=items)


def B_attention(items, titre="Piegues frequents"):
    return bloc(titre, type="attention", items=items)


def B_exemples(items, titre="Exemples et applications"):
    return bloc(titre, type="exemples", items=items)


def BLOCS(intro, eq, leg, grille, liste, etapes, attention, exemples, ftitre=None):
    if ftitre is None:
        return [B_intro(intro), B_formule(eq, leg), B_grille(grille),
                B_liste(liste), B_etapes(etapes), B_attention(attention), B_exemples(exemples)]
    return [B_intro(intro), B_formule(eq, leg, ftitre), B_grille(grille),
            B_liste(liste), B_etapes(etapes), B_attention(attention), B_exemples(exemples)]


